// UpdateInstanceRequest defines model for UpdateInstanceRequest.
type UpdateInstanceRequest struct {
	// CategoryIds Replaces the whole set; an empty array removes all categories
	CategoryIds *[]openapi_types.UUID `json:"category_ids,omitempty"`

	// Description An empty string clears the description
	Description  *string    `json:"description,omitempty"`
	PlannedEnd   *time.Time `json:"planned_end,omitempty"`
	PlannedStart *time.Time `json:"planned_start,omitempty"`

	// Recurrence Repeat rule of a regular task. The first occurrence slot of a new task is its
	// `planned_start`–`planned_end`; times are repeated by the wall clock of the
	// user's time zone, also across daylight saving changes. Error codes:
	// `no_occurrences` (the rule has no occurrence from the start on).
	Recurrence *Recurrence `json:"recurrence,omitempty"`
	Title      *string     `json:"title,omitempty"`

	// Visibility With scope `this` the task's own value; with `following` and `all` the value of the
	// series, which also takes the values of their own off the occurrences concerned and
	// does not re-create them. As any edit of one occurrence, a value of its own sets
	// the occurrence apart from the series (`is_detached`).
	Visibility *Visibility `json:"visibility,omitempty"`
}

