// ServerInterface represents all server handlers.
type ServerInterface interface {
	// GetAuthConfig How a browser can sign in
	// (GET /auth/config)
	GetAuthConfig(w http.ResponseWriter, r *http.Request)
	// LoginDev Sign in without Telegram (development only)
	// (POST /auth/dev)
	LoginDev(w http.ResponseWriter, r *http.Request)
	// Logout End the current session
	// (POST /auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// LoginTelegram Sign in with Telegram Mini App init data
	// (POST /auth/telegram)
	LoginTelegram(w http.ResponseWriter, r *http.Request)
	// LoginTelegramWidget Sign in on the web with the Telegram Login Widget
	// (POST /auth/telegram-widget)
	LoginTelegramWidget(w http.ResponseWriter, r *http.Request)
	// ListCategories All categories of the user, archived ones included
	// (GET /categories)
	ListCategories(w http.ResponseWriter, r *http.Request)
	// CreateCategory Create a category
	// (POST /categories)
	CreateCategory(w http.ResponseWriter, r *http.Request)
	// DeleteCategory Delete a category together with all its subcategories
	// (DELETE /categories/{id})
	DeleteCategory(w http.ResponseWriter, r *http.Request, id CategoryId)
	// UpdateCategory Rename or recolor a category; omitted fields stay as they are
	// (PATCH /categories/{id})
	UpdateCategory(w http.ResponseWriter, r *http.Request, id CategoryId)
	// ArchiveCategory Archive a category together with all its subcategories
	// (POST /categories/{id}/archive)
	ArchiveCategory(w http.ResponseWriter, r *http.Request, id CategoryId)
	// MoveCategory Move a category to another parent or to the top level
	// (POST /categories/{id}/move)
	MoveCategory(w http.ResponseWriter, r *http.Request, id CategoryId)
	// UnarchiveCategory Restore one archived category
	// (POST /categories/{id}/unarchive)
	UnarchiveCategory(w http.ResponseWriter, r *http.Request, id CategoryId)
	// GetFreeTime Free time shared by the user and chosen partners
	// (GET /free-time)
	GetFreeTime(w http.ResponseWriter, r *http.Request, params GetFreeTimeParams)
	// ListHabits All habits of the user, archived ones included
	// (GET /habits)
	ListHabits(w http.ResponseWriter, r *http.Request)
	// CreateHabit Create a habit
	// (POST /habits)
	CreateHabit(w http.ResponseWriter, r *http.Request)
	// GetHabitsToday Habits for today, with today's marks
	// (GET /habits/today)
	GetHabitsToday(w http.ResponseWriter, r *http.Request)
	// DeleteHabit Delete a habit with its marks
	// (DELETE /habits/{id})
	DeleteHabit(w http.ResponseWriter, r *http.Request, id HabitId)
	// GetHabit One habit
	// (GET /habits/{id})
	GetHabit(w http.ResponseWriter, r *http.Request, id HabitId)
	// UpdateHabit Change a habit
	// (PATCH /habits/{id})
	UpdateHabit(w http.ResponseWriter, r *http.Request, id HabitId)
	// ArchiveHabit Archive a habit
	// (POST /habits/{id}/archive)
	ArchiveHabit(w http.ResponseWriter, r *http.Request, id HabitId)
	// SetHabitLog Set the value of a habit on a local date
	// (PUT /habits/{id}/logs/{date})
	SetHabitLog(w http.ResponseWriter, r *http.Request, id HabitId, date openapi_types.Date)
	// ClearHabitPlacement Take a habit out of the grid
	// (DELETE /habits/{id}/placement)
	ClearHabitPlacement(w http.ResponseWriter, r *http.Request, id HabitId)
	// SetHabitPlacement Put a habit in the grid, or change its time and length there
	// (PUT /habits/{id}/placement)
	SetHabitPlacement(w http.ResponseWriter, r *http.Request, id HabitId)
	// GetHabitStats Streaks, percentages and the heat map of a habit
	// (GET /habits/{id}/stats)
	GetHabitStats(w http.ResponseWriter, r *http.Request, id HabitId, params GetHabitStatsParams)
	// UnarchiveHabit Bring an archived habit back
	// (POST /habits/{id}/unarchive)
	UnarchiveHabit(w http.ResponseWriter, r *http.Request, id HabitId)
	// GetHealth Liveness and database readiness probe
	// (GET /healthz)
	GetHealth(w http.ResponseWriter, r *http.Request)
	// ListInstances Tasks planned within a time window
	// (GET /instances)
	ListInstances(w http.ResponseWriter, r *http.Request, params ListInstancesParams)
	// ListRunningInstances Tasks whose timer is running, from whatever day they were started
	// (GET /instances/running)
	ListRunningInstances(w http.ResponseWriter, r *http.Request)
	// CreateUnplanned Add a task outside the plan
	// (POST /instances/unplanned)
	CreateUnplanned(w http.ResponseWriter, r *http.Request)
	// DeleteInstance Delete a task
	// (DELETE /instances/{id})
	DeleteInstance(w http.ResponseWriter, r *http.Request, id InstanceId, params DeleteInstanceParams)
	// UpdateInstance Edit a task; omitted fields stay as they are
	// (PATCH /instances/{id})
	UpdateInstance(w http.ResponseWriter, r *http.Request, id InstanceId, params UpdateInstanceParams)
	// CompleteInstance Done in one tap: the fact becomes equal to the plan
	// (POST /instances/{id}/complete)
	CompleteInstance(w http.ResponseWriter, r *http.Request, id InstanceId)
	// RescheduleInstance Move a task to another time, leaving a trail
	// (POST /instances/{id}/reschedule)
	RescheduleInstance(w http.ResponseWriter, r *http.Request, id InstanceId)
	// StartInstance Start a timer: the fact begins now
	// (POST /instances/{id}/start)
	StartInstance(w http.ResponseWriter, r *http.Request, id InstanceId)
	// StopInstance Stop the timer: the fact ends now and the task is done
	// (POST /instances/{id}/stop)
	StopInstance(w http.ResponseWriter, r *http.Request, id InstanceId)
	// UpdateTracking Edit the status, the fact and the comment by hand
	// (PATCH /instances/{id}/tracking)
	UpdateTracking(w http.ResponseWriter, r *http.Request, id InstanceId)
	// GetMe Current user with settings
	// (GET /me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// UpdateMySettings Change settings; omitted fields stay as they are
	// (PATCH /me/settings)
	UpdateMySettings(w http.ResponseWriter, r *http.Request)
	// ListPartners Partners of the user
	// (GET /partners)
	ListPartners(w http.ResponseWriter, r *http.Request)
	// CreatePartnerInvite Create an invite link
	// (POST /partners/invites)
	CreatePartnerInvite(w http.ResponseWriter, r *http.Request)
	// AcceptPartnerInvite Accept an invite
	// (POST /partners/invites/accept)
	AcceptPartnerInvite(w http.ResponseWriter, r *http.Request)
	// RemovePartner Break the link
	// (DELETE /partners/{id})
	RemovePartner(w http.ResponseWriter, r *http.Request, id PartnerId)
	// SetPartnerAccess Give or take back access for a partner
	// (PUT /partners/{id}/access)
	SetPartnerAccess(w http.ResponseWriter, r *http.Request, id PartnerId)
	// GetPartnerBusy The busy time of a partner
	// (GET /partners/{id}/busy)
	GetPartnerBusy(w http.ResponseWriter, r *http.Request, id PartnerId, params GetPartnerBusyParams)
	// GetGlobalReminders The master switch, the quiet hours and the default reminders
	// (GET /reminders/global)
	GetGlobalReminders(w http.ResponseWriter, r *http.Request)
	// SetGlobalReminders Replace the global reminder settings
	// (PUT /reminders/global)
	SetGlobalReminders(w http.ResponseWriter, r *http.Request)
	// DeleteReminders Take the level's own settings away, so that it inherits again
	// (DELETE /reminders/{scope}/{id})
	DeleteReminders(w http.ResponseWriter, r *http.Request, scope string, id openapi_types.UUID)
	// GetReminders Reminder settings of a category, a series, one occurrence or a habit
	// (GET /reminders/{scope}/{id})
	GetReminders(w http.ResponseWriter, r *http.Request, scope string, id openapi_types.UUID)
	// SetReminders Give a level reminder settings of its own
	// (PUT /reminders/{scope}/{id})
	SetReminders(w http.ResponseWriter, r *http.Request, scope string, id openapi_types.UUID)
	// GetSeries The template of a regular task
	// (GET /series/{id})
	GetSeries(w http.ResponseWriter, r *http.Request, id SeriesId)
	// GetStats Statistics of a period, by the fact
	// (GET /stats)
	GetStats(w http.ResponseWriter, r *http.Request, params GetStatsParams)
	// CreateTask Create a one-off task
	// (POST /tasks)
	CreateTask(w http.ResponseWriter, r *http.Request)
}

